  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = 7x^3 - 2x^2 + x.', '["7x^3 - 2x^2 + x", "21x^3 - 4x^2 + x", "42x - 4", "21x^2 - 4x + 1"]'::jsonb, 3, 'Applying the power rule term by term: d/dx[7x^3 - 2x^2 + x] = 21*x**2 - 4*x + 1.', 'Derivative of the Power Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = x^6 - 4x.', '["30x^4", "6x^5 - 4", "x^6 - 4x", "6x^6 - 4x"]'::jsonb, 1, 'Applying the power rule term by term: d/dx[x^6 - 4x] = 6*x**5 - 4.', 'Derivative of the Power Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = 2x^7 + 5.', '["14x^6", "14x^7", "84x^5", "2x^7 + 5"]'::jsonb, 0, 'Applying the power rule term by term: d/dx[2x^7 + 5] = 14*x**6.', 'Derivative of the Power Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = x^2/2 - 3x.', '["1", "x - 3", "x^2/2 - 3x", "x^2 - 3x"]'::jsonb, 1, 'Applying the power rule term by term: d/dx[x^2/2 - 3x] = x - 3.', 'Derivative of the Power Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = sin(x).', '["cos(x) + 1", "cos(x)", "sin(x)", "-cos(x)"]'::jsonb, 1, 'Using the standard trigonometric derivative rules, d/dx[sin(x)] = cos(x).', 'Derivatives of Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = cos(x).', '["sin(x)", "-sin(x)", "cos(x)", "1 - sin(x)"]'::jsonb, 1, 'Using the standard trigonometric derivative rules, d/dx[cos(x)] = -sin(x).', 'Derivatives of Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = tan(x).', '["-1/cos(x)^2", "tan(x)", "cos(x)", "cos(x)^(-2)"]'::jsonb, 3, 'Using the standard trigonometric derivative rules, d/dx[tan(x)] = tan(x)**2 + 1.', 'Derivatives of Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = 3sin(x).', '["cos(x)", "-3cos(x)", "3cos(x)", "3sin(x)"]'::jsonb, 2, 'Using the standard trigonometric derivative rules, d/dx[3sin(x)] = 3*cos(x).', 'Derivatives of Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = sin(x) + cos(x).', '["-sin(x) + cos(x)", "sin(x) - cos(x)", "sin(x) + cos(x)", "cos(x)"]'::jsonb, 0, 'Using the standard trigonometric derivative rules, d/dx[sin(x) + cos(x)] = -sin(x) + cos(x).', 'Derivatives of Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of f(x) = x^2·sin(x).', '["x(xcos(x) + 2sin(x))", "x^2cos(x)", "2xcos(x)", "2xsin(x)"]'::jsonb, 0, 'Product Rule: (uv)'' = u''v + uv''. Here u''=2*x, v''=cos(x), giving f''(x) = x**2*cos(x) + 2*x*sin(x).', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of f(x) = x·cos(x).', '["-xsin(x)", "-xsin(x) + cos(x)", "cos(x)", "-sin(x)"]'::jsonb, 1, 'Product Rule: (uv)'' = u''v + uv''. Here u''=1, v''=-sin(x), giving f''(x) = -x*sin(x) + cos(x).', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of f(x) = x^2·x + 1.', '["x^2", "2x", "2x^2 + 2x", "3x^2 + 2x"]'::jsonb, 3, 'Product Rule: (uv)'' = u''v + uv''. Here u''=2*x, v''=1, giving f''(x) = 3*x**2 + 2*x.', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Product Rule, find the derivative of f(x) = sin(x)·cos(x).', '["cos(2x)", "-sin(x)^2", "cos(x)^2", "-sin(2x)/2"]'::jsonb, 0, 'Product Rule: (uv)'' = u''v + uv''. Here u''=cos(x), v''=-sin(x), giving f''(x) = -sin(x)**2 + cos(x)**2.', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of f(x) = (x)/(x + 1).', '["1/(x^2 + 2x + 1)", "1/(x + 1)", "1", "2x/(x^2 + 2x + 1) + 1/(x^2 + 2x + 1)"]'::jsonb, 0, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=1, v''=1, giving f''(x) = (x + 1)**(-2).', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of f(x) = (x^2)/(x - 2).', '["x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)", "2x", "2x/(x - 2)", "3x^2/(x^2 - 4x + 4) - 4x/(x^2 - 4x + 4)"]'::jsonb, 0, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=2*x, v''=1, giving f''(x) = x*(x - 4)/(x**2 - 4*x + 4).', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of f(x) = (sin(x))/(x).', '["(xcos(x) + sin(x))/x^2", "(xcos(x) - sin(x))/x^2", "cos(x)/x", "cos(x)"]'::jsonb, 1, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=cos(x), v''=1, giving f''(x) = (x*cos(x) - sin(x))/x**2.', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Quotient Rule, find the derivative of f(x) = (2x + 1)/(x^2 + 1).', '["1/x", "-2x^2/(x^4 + 2x^2 + 1) - 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)", "2/(x^2 + 1)", "6x^2/(x^4 + 2x^2 + 1) + 2x/(x^4 + 2x^2 + 1) + 2/(x^4 + 2x^2 + 1)"]'::jsonb, 1, 'Quotient Rule: (u/v)'' = (u''v - uv'')/v². Here u''=2, v''=2*x, giving f''(x) = 2*(-x**2 - x + 1)/(x**4 + 2*x**2 + 1).', 'Rules of Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of f(x) = (x^2 + 1)^3.', '["3x^4 + 6x^2 + 3", "6x^5 + 12x^3 + 6x", "8x^3", "6x^7 + 18x^5 + 18x^3 + 6x"]'::jsonb, 1, 'Chain Rule: with u=x^2 + 1, D[u^3] = 3u^2·Du = 3(x^2 + 1)^2·(2*x) = 6*x**5 + 12*x**3 + 6*x.', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of f(x) = (2x - 5)^4.', '["64x^3 - 480x^2 + 1200x - 1000", "16", "128x^4 - 1280x^3 + 4800x^2 - 8000x + 5000", "32x^3 - 240x^2 + 600x - 500"]'::jsonb, 0, 'Chain Rule: with u=2x - 5, D[u^4] = 4u^3·Du = 4(2x - 5)^3·(2) = 64*x**3 - 480*x**2 + 1200*x - 1000.', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the Chain Rule, find the derivative of f(x) = (x^3 - 2x)^2.', '["2x^3 - 4x", "9x^4 - 12x^2 + 4", "6x^5 - 16x^3 + 8x", "6x^8 - 28x^6 + 40x^4 - 16x^2"]'::jsonb, 2, 'Chain Rule: with u=x^3 - 2x, D[u^2] = 2u^1·Du = 2(x^3 - 2x)^1·(3*x**2 - 2) = 6*x**5 - 16*x**3 + 8*x.', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = sin(2x + 3).', '["2cos(2x + 3)", "cos(2x + 3)", "-2cos(2x + 3)", "sin(2)"]'::jsonb, 0, 'By the Chain Rule, D[sin(u)] = cos(u)·Du, with u=2x + 3, Du=2, giving f''(x) = 2*cos(2*x + 3).', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = sin(x^2).', '["-2xcos(x^2)", "sin(2x)", "cos(x^2)", "2xcos(x^2)"]'::jsonb, 3, 'By the Chain Rule, D[sin(u)] = cos(u)·Du, with u=x^2, Du=2*x, giving f''(x) = 2*x*cos(x**2).', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = sin(3x - 1).', '["cos(3x - 1)", "-3cos(3x - 1)", "3cos(3x - 1)", "sin(3)"]'::jsonb, 2, 'By the Chain Rule, D[sin(u)] = cos(u)·Du, with u=3x - 1, Du=3, giving f''(x) = 3*cos(3*x - 1).', 'The Chain Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to y = x^2 - 4x + 3 at x = 1.', '["-2", "-1", "0", "2"]'::jsonb, 0, 'The slope is f''(1) where f''(x)=2*x - 4, so f''(1) = -2.', 'The Derivative', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to y = x^3 - 3x at x = 2.', '["2", "11", "-9", "9"]'::jsonb, 3, 'The slope is f''(2) where f''(x)=3*x**2 - 3, so f''(2) = 9.', 'The Derivative', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to y = 2x^2 + 1 at x = -1.', '["-4", "3", "-2", "4"]'::jsonb, 0, 'The slope is f''(-1) where f''(x)=4*x, so f''(-1) = -4.', 'The Derivative', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the slope of the tangent line to y = x^2 at x = 3.', '["9", "6", "-6", "8"]'::jsonb, 1, 'The slope is f''(3) where f''(x)=2*x, so f''(3) = 6.', 'The Derivative', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x² + y² = 25, find dy/dx at the point (3,4).', '["4/3", "-4/3", "3/4", "-3/4"]'::jsonb, 3, 'Differentiating implicitly: 2x + 2y(dy/dx) = 0, so dy/dx = -x/y. At (3,4): dy/dx = -3/4.', 'Implicit Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If x³ + y³ = 9, find dy/dx at the point (1,2).', '["1/4", "-4", "4", "-1/4"]'::jsonb, 3, 'Differentiating implicitly: 3x² + 3y²(dy/dx) = 0, so dy/dx = -x²/y². At (1,2): dy/dx = -1/4.', 'Implicit Differentiation', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of f(x) = x^3 - 3x + 1.', '["0", "-1, 1", "no critical points", "0, 2"]'::jsonb, 1, 'f''(x) = 3*x**2 - 3. Setting f''(x) = 0 and solving gives x = -1, 1.', 'Maxima and Minima', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of f(x) = x^2 - 6x + 5.', '["no critical points", "3", "4", "2"]'::jsonb, 1, 'f''(x) = 2*x - 6. Setting f''(x) = 0 and solving gives x = 3.', 'Maxima and Minima', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of f(x) = 2x^3 - 3x^2 - 12x + 4.', '["0, 3", "0", "no critical points", "-1, 2"]'::jsonb, 3, 'f''(x) = 6*x**2 - 6*x - 12. Setting f''(x) = 0 and solving gives x = -1, 2.', 'Maxima and Minima', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the critical point(s) of f(x) = x^3 - 12x.', '["-2, 2", "-1, 3", "0", "no critical points"]'::jsonb, 0, 'f''(x) = 3*x**2 - 12. Setting f''(x) = 0 and solving gives x = -2, 2.', 'Maxima and Minima', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 1 of f(x) = x^3 - 3x, the Second Derivative Test shows this is a:', '["point of inflection", "relative maximum", "not a critical point", "relative minimum"]'::jsonb, 3, 'f''''(x) = 6*x, so f''''(1) = 6, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = -1 of f(x) = x^3 - 3x, the Second Derivative Test shows this is a:', '["relative minimum", "not a critical point", "relative maximum", "point of inflection"]'::jsonb, 2, 'f''''(x) = 6*x, so f''''(-1) = -6, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 2 of f(x) = x^2 - 4x + 7, the Second Derivative Test shows this is a:', '["relative maximum", "not a critical point", "relative minimum", "point of inflection"]'::jsonb, 2, 'f''''(x) = 2, so f''''(2) = 2, which is positive, indicating a relative minimum.', 'The Second Derivative Test for Extremum', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'At the critical point x = 3 of f(x) = -x^2 + 6x - 5, the Second Derivative Test shows this is a:', '["not a critical point", "relative maximum", "relative minimum", "point of inflection"]'::jsonb, 1, 'f''''(x) = -2, so f''''(3) = -2, which is negative, indicating a relative maximum.', 'The Second Derivative Test for Extremum', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For f(x) = x² - 4x + 3, on which interval is f increasing?', '["(2, ∞)", "(-∞, ∞)", "(0, 2)", "(-∞, 2)"]'::jsonb, 0, 'f''(x) = 2x - 4, which is positive when x > 2, so f is increasing on (2, ∞).', 'Monotonicity of a Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For f(x) = x³ - 3x, on which interval is f decreasing?', '["(-∞, ∞)", "(-∞,-1)", "(-1, 1)", "(1, ∞)"]'::jsonb, 2, 'f''(x) = 3x²-3 = 3(x-1)(x+1), which is negative for -1<x<1, so f is decreasing on (-1,1).', 'Monotonicity of a Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to y = x^2 at x = -1.', '["y = -2x + 1", "y = -2x - 1", "y = 1x - 2", "y = 2x - 1"]'::jsonb, 1, 'f(-1)=1, f''(-1)=-2. Using y - f(a) = f''(a)(x-a): y = -2(x--1) + 1 = y = -2x - 1.', 'Tangents and Normals', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to y = x^2 - 3x + 2 at x = 1.', '["y = 0x - 1", "y = 1x + 1", "y = -1x + 1", "y = -1x"]'::jsonb, 2, 'f(1)=0, f''(1)=-1. Using y - f(a) = f''(a)(x-a): y = -1(x-1) + 0 = y = -1x + 1.', 'Tangents and Normals', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to y = x^3 at x = 1.', '["y = -3x - 2", "y = 3x + 1", "y = 3x - 2", "y = 1x + 3"]'::jsonb, 2, 'f(1)=1, f''(1)=3. Using y - f(a) = f''(a)(x-a): y = 3(x-1) + 1 = y = 3x - 2.', 'Tangents and Normals', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the equation of the tangent line to y = x^2 at x = 3.', '["y = -6x - 9", "y = 9x + 6", "y = 6x + 9", "y = 6x - 9"]'::jsonb, 3, 'f(3)=9, f''(3)=6. Using y - f(a) = f''(a)(x-a): y = 6(x-3) + 9 = y = 6x - 9.', 'Tangents and Normals', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate lim(x→0) [sin(x)/x].', '["1", "does not exist", "oo", "0"]'::jsonb, 0, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 1.', 'Indeterminate Forms and L''Hopital''s Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate lim(x→1) [(x^2 - 1)/(x - 1)].', '["2", "oo", "0", "does not exist"]'::jsonb, 0, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 2.', 'Indeterminate Forms and L''Hopital''s Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate lim(x→0) [(1 - cos(x))/x^2].', '["does not exist", "oo", "1/2", "0"]'::jsonb, 2, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 1/2.', 'Indeterminate Forms and L''Hopital''s Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Use L''Hopital''s Rule to evaluate lim(x→2) [(x^2 - 4)/(x - 2)].', '["0", "oo", "4", "does not exist"]'::jsonb, 2, 'This is a 0/0 form. Differentiating numerator and denominator separately and taking the limit gives 4.', 'Indeterminate Forms and L''Hopital''s Rule', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'For f(x) = x³ - 6x² + 9x, find the x-coordinate of the point of inflection.', '["-2", "3", "0", "2"]'::jsonb, 3, 'f''''(x) = 6x - 12. Setting f''''(x)=0 gives x=2, where concavity changes.', 'Concavity and Points of Inflection', true),
