  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find ∫ 3sin(x) dx.', '["-3cos(x) + C", "sec(x) + C", "-3sin(x) + C", "3cos(x) + C"]'::jsonb, 0, 'Using the standard antiderivative formulas for trigonometric functions: ∫3sin(x) dx = -3cos(x) + C.', 'Antiderivatives of Some Elementary Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from 0 to 2 of x^2 dx.', '["5/3", "-8/3", "8/3", "11/3"]'::jsonb, 2, 'An antiderivative is F(x) = x^3/3. By the Fundamental Theorem, the definite integral is F(2) - F(0) = 8/3 - (0) = 8/3.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from 1 to 4 of 3x - 1 dx.', '["41/2", "-39/2", "20", "39/2"]'::jsonb, 3, 'An antiderivative is F(x) = 3x^2/2 - x. By the Fundamental Theorem, the definite integral is F(4) - F(1) = 20 - (1/2) = 39/2.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from 0 to 3 of x^2 - 4x + 3 dx.', '["-1", "2", "0", "1"]'::jsonb, 2, 'An antiderivative is F(x) = x^3/3 - 2x^2 + 3x. By the Fundamental Theorem, the definite integral is F(3) - F(0) = 0 - (0) = 0.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from -1 to 2 of 2x + 1 dx.', '["7", "5", "6", "-6"]'::jsonb, 2, 'An antiderivative is F(x) = x^2 + x. By the Fundamental Theorem, the definite integral is F(2) - F(-1) = 6 - (0) = 6.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from 0 to 1 of x^3 dx.', '["-3/4", "1/4", "-1/4", "5/4"]'::jsonb, 1, 'An antiderivative is F(x) = x^4/4. By the Fundamental Theorem, the definite integral is F(1) - F(0) = 1/4 - (0) = 1/4.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Evaluate ∫ from -1 to 1 of 4 - x^2 dx.', '["-22/3", "22/3", "25/3", "11/3"]'::jsonb, 1, 'An antiderivative is F(x) = -x^3/3 + 4x. By the Fundamental Theorem, the definite integral is F(1) - F(-1) = 11/3 - (-11/3) = 22/3.', 'Fundamental Theorem of Integral Calculus', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = x^2, the x-axis, x=0, and x=2.', '["16/3", "11/3", "-8/3", "8/3"]'::jsonb, 3, 'Area = ∫ from 0 to 2 of x^2 dx = 8/3.', 'Areas of Plane Regions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = 3x, the x-axis, x=0, and x=4.', '["-24", "25", "48", "24"]'::jsonb, 3, 'Area = ∫ from 0 to 4 of 3x dx = 24.', 'Areas of Plane Regions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = 4 - x^2, the x-axis, x=-2, and x=2.', '["32/3", "-32/3", "35/3", "64/3"]'::jsonb, 0, 'Area = ∫ from -2 to 2 of 4 - x^2 dx = 32/3.', 'Areas of Plane Regions', true),
