  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = x + 3 and y = x^2 - 1 between x=-1 and x=1.', '["6", "-22/3", "22/3", "28/3"]'::jsonb, 2, 'Area = ∫ from -1 to 1 of [(x + 3) - (x^2 - 1)] dx = ∫ from -1 to 1 of -x^2 + x + 4 dx = 22/3.', 'Areas of Plane Regions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = 6 - x and y = x^2 between x=-3 and x=2.', '["65/2", "-125/6", "137/6", "125/6"]'::jsonb, 3, 'Area = ∫ from -3 to 2 of [(6 - x) - (x^2)] dx = ∫ from -3 to 2 of -x^2 - x + 6 dx = 125/6.', 'Areas of Plane Regions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the area of the region bounded by y = x + 5 and y = x^2 - 1 between x=-2 and x=3.', '["137/6", "55/2", "-125/6", "125/6"]'::jsonb, 3, 'Area = ∫ from -2 to 3 of [(x + 5) - (x^2 - 1)] dx = ∫ from -2 to 3 of -x^2 + x + 6 dx = 125/6.', 'Areas of Plane Regions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving y = x about the x-axis from x=0 to x=4.', '["128pi/3", "-64pi/3", "8pi", "64pi/3"]'::jsonb, 3, 'V = π∫ from 0 to 4 of (x)² dx = 64*pi/3.', 'The Disc Method', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving y = sqrt(x) about the x-axis from x=0 to x=4.', '["16pi", "8pi", "16pi/3", "-8pi"]'::jsonb, 1, 'V = π∫ from 0 to 4 of (sqrt(x))² dx = 8*pi.', 'The Disc Method', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving y = 2 about the x-axis from x=0 to x=3.', '["12pi", "24pi", "-12pi", "6pi"]'::jsonb, 0, 'V = π∫ from 0 to 3 of (2)² dx = 12*pi.', 'The Disc Method', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using the disc method, find the volume of the solid formed by revolving y = x^2 about the x-axis from x=0 to x=1.', '["pi/3", "-pi/5", "2pi/5", "pi/5"]'::jsonb, 3, 'V = π∫ from 0 to 1 of (x^2)² dx = pi/5.', 'The Disc Method', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = ln(3x^2 + 5).', '["-6x/(3x^2 + 5)", "1/(3x^2 + 5)", "6x/(3x^2 + 5)", "6x"]'::jsonb, 2, 'By the Chain Rule, D[ln(u)] = (Du)/u. With u=3x^2 + 5, Du=6*x, giving f''(x) = 6x/(3x^2 + 5).', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = ln(cos(x)).', '["1/cos(x)", "-sin(x)", "tan(x)", "-tan(x)"]'::jsonb, 3, 'By the Chain Rule, D[ln(u)] = (Du)/u. With u=cos(x), Du=-sin(x), giving f''(x) = -tan(x).', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = ln(x^3 - 2).', '["1/(x^3 - 2)", "3x^2/(x^3 - 2)", "-3x^2/(x^3 - 2)", "3x^2"]'::jsonb, 1, 'By the Chain Rule, D[ln(u)] = (Du)/u. With u=x^3 - 2, Du=3*x**2, giving f''(x) = 3x^2/(x^3 - 2).', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = ln(5x - 1).', '["-5/(5x - 1)", "5", "5/(5x - 1)", "1/(5x - 1)"]'::jsonb, 2, 'By the Chain Rule, D[ln(u)] = (Du)/u. With u=5x - 1, Du=5, giving f''(x) = 5/(5x - 1).', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = e^(4x).', '["-4e^(4x)", "4e^(4x)", "e^(4x)", "4"]'::jsonb, 1, 'By the Chain Rule, D[e^u] = e^u·Du. With u=4x, Du=4, giving f''(x) = 4e^(4x).', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = e^(x^2).', '["-2xe^(x^2)", "2x", "2xe^(x^2)", "e^(x^2)"]'::jsonb, 2, 'By the Chain Rule, D[e^u] = e^u·Du. With u=x^2, Du=2*x, giving f''(x) = 2xe^(x^2).', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = e^(sin(x)).', '["e^(sin(x))", "cos(x)", "-e^(sin(x))cos(x)", "e^(sin(x))cos(x)"]'::jsonb, 3, 'By the Chain Rule, D[e^u] = e^u·Du. With u=sin(x), Du=cos(x), giving f''(x) = e^(sin(x))cos(x).', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = e^(2x - 1).', '["2", "2e^(2x - 1)", "-2e^(2x - 1)", "e^(2x - 1)"]'::jsonb, 1, 'By the Chain Rule, D[e^u] = e^u·Du. With u=2x - 1, Du=2, giving f''(x) = 2e^(2x - 1).', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = asin(x).', '["-1/sqrt(1 - x^2)", "1/(x^2 + 1)", "1/sqrt(1 - x^2)", "sqrt(1 - x^2)"]'::jsonb, 2, 'Using the standard derivative formula for inverse trigonometric functions: d/dx[asin(x)] = 1/sqrt(1 - x^2).', 'Inverse Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = acos(x).', '["1/sqrt(1 - x^2)", "sqrt(1 - x^2)", "1/(x^2 + 1)", "-1/sqrt(1 - x^2)"]'::jsonb, 3, 'Using the standard derivative formula for inverse trigonometric functions: d/dx[acos(x)] = -1/sqrt(1 - x^2).', 'Inverse Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find the derivative of f(x) = atan(x).', '["sqrt(1 - x^2)", "1/(x^2 + 1)", "-1/(x^2 + 1)", "1/sqrt(1 - x^2)"]'::jsonb, 1, 'Using the standard derivative formula for inverse trigonometric functions: d/dx[atan(x)] = 1/(x^2 + 1).', 'Inverse Trigonometric Functions', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If f(x) = ln(x² + 1), find f''(2).', '["4/3", "2/5", "1/5", "4/5"]'::jsonb, 3, 'f''(x) = 2x/(x²+1). At x=2: f''(2) = 4/5.', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'If f(x) = e^(3x), find f''(0).', '["e^(3)", "0", "3", "1"]'::jsonb, 2, 'f''(x) = 3e^(3x). At x=0: f''(0) = 3e⁰ = 3.', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find ∫ 1/x dx.', '["1/x² + C", "-1/x² + C", "ln|x| + C", "x·ln(x) + C"]'::jsonb, 2, 'The antiderivative of 1/x is the natural logarithm of the absolute value: ln|x| + C.', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find ∫ 2/(2x+1) dx.', '["2ln|2x+1| + C", "ln|x| + C", "(1/2)ln|2x+1| + C", "ln|2x+1| + C"]'::jsonb, 3, 'With u=2x+1, du=2dx, so ∫2/(2x+1)dx = ∫(1/u)du = ln|u| + C = ln|2x+1| + C.', 'The Natural Logarithmic Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Find ∫ e^(5x) dx.', '["(1/5)e^(5x) + C", "5e^(5x) + C", "e^(5x) + C", "e^(5x)/x + C"]'::jsonb, 0, 'With u=5x, du=5dx, so ∫e^(5x)dx = (1/5)∫e^u du = (1/5)e^(5x) + C.', 'The Exponential Function', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using substitution, find ∫ (3x + 5)^4 dx.', '["81x^5/5 + 135x^4 + 450x^3 + 750x^2 + 625x + C", "243x^5/5 + 405x^4 + 1350x^3 + 2250x^2 + 1875x + C", "-81x^5/5 - 135x^4 - 450x^3 - 750x^2 - 625x + C", "324x^3 + 1620x^2 + 2700x + 1500 + C"]'::jsonb, 0, 'With an appropriate linear substitution u for the inner expression, ∫(3x + 5)^4 dx = 81x^5/5 + 135x^4 + 450x^3 + 750x^2 + 625x + C.', 'Method of Substitution', true),
  ('mth-121-calculus', 'MTH 121: Functions, Limits, Differentiation & Integration', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Mathematics', '100 Level', 'Using substitution, find ∫ cos(2x + 1) dx.', '["-sin(2x + 1)/2 + C", "3sin(2x + 1)/2 + C", "sin(2x + 1)/2 + C", "-2sin(2x + 1) + C"]'::jsonb, 2, 'With an appropriate linear substitution u for the inner expression, ∫cos(2x + 1) dx = sin(2x + 1)/2 + C.', 'Method of Substitution', true),
